import { useEffect, useId, useRef, type CSSProperties, type PointerEvent, type ReactNode } from 'react';
import { Pin } from 'lucide-react';
import { isLite } from '@/hooks/usePerfMode';
import { cn } from '@/lib/utils';
import TeamLogo from '@/components/brand/TeamLogo';
import { POSITION_NAMES } from '@/utils/playerMeta';
import { findNFLTeam } from '@/utils/nflTeams';
import type { GamePlayer } from '@/config/ovr';
import { finishLabel, prizmInfo, prizmSerial, tierLabel, variantLabel, variantShort, type Finish, type PrizmCopy, type Tier, type Variant } from '@/utils/collection';
import type { AutographChoice } from './autograph/sample';
import VariantArt from './art/VariantArt';
import type { FaceStat } from './cardStats';
import { FINISH_ICON, TIER_ICON } from './rarityIcons';
import { cardFaceVars } from './cardFace';
import { loadMarket } from '@/utils/useMarket';
import './collection.css';
import { displayName, surnameOf } from '@/utils/displayName';
import { CAREER_LABEL } from '@/config/ovr';

const motionOk = () => {
  try {
    return !isLite() && !window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  } catch {
    return false;
  }
};

/**
 * One IntersectionObserver for every idle card: data-vis="on" while the card is on screen (CSS runs the idle loops only
 * then), so off-screen Holo / Legendary cards cost nothing.
 */
let idleIO: IntersectionObserver | null = null;
const observeIdle = (el: HTMLElement) => {
  if (typeof IntersectionObserver === 'undefined') return undefined;
  idleIO ??= new IntersectionObserver(
    (entries) =>
      entries.forEach((e) => {
        const t = e.target as HTMLElement;
        if (e.isIntersecting) t.dataset.vis = 'on';
        else delete t.dataset.vis;
      }),
    { rootMargin: '80px' },
  );
  idleIO.observe(el);
  return () => {
    idleIO?.unobserve(el);
    delete el.dataset.vis;
  };
};
/** Stable 0–8 s offset per player for the idle loops. */
const idleOffset = (name: string) => {
  let h = 0;
  for (let i = 0; i < name.length; i++) h = (h * 31 + name.charCodeAt(i)) | 0;
  return Math.abs(h) % 8000;
};

/** Surname for the name bar ("Odell Beckham Jr." → "Beckham"). */

