const SPARKS = [
  [12, 18],
  [84, 12],
  [90, 46],
  [8, 58],
  [70, 30],
  [30, 8],
  [50, 88],
  [22, 82],
] as const;

export interface CollectibleCardProps {
  player: GamePlayer;
  /** Player tier (Common to Legendary): sets the frame colour (copper, steel blue, amethyst, black-ember) */
  tier: Tier;
  /** Finish (Base, Silver, Gold, Holo): the treatment on top; ignored while locked */
  finish: Finish;
  /** Art variant (Prizm number … Autograph); omitted = the plain baseline jersey */
  variant?: Variant;
  /** Autograph variant: the autograph it shows (a pull), or 'sample' (galleries); omitted = his best owned one, else a sample */
  autograph?: AutographChoice;
  /** Kit the art wears (a stored kit id: 'home', an alternate's or era kit's id); omitted = the old fixed roll (uniformFor) */
  kit?: string;
  /** Prizm number: the colour parallel it shows (colour + serial); omitted = plain Prizm */
  prizm?: PrizmCopy;
  owned: boolean;
  ovr?: number | null;
  number?: number | null;
  /** Six face stats (cardStats.faceStatsFor) */
  stats?: FaceStat[];
  /** Set number, e.g. 12 of 185 */
  setNo?: number;
  setTotal?: number;
  /** Shown to screen readers on locked cards */
  hint?: string;
  /** Makes the card a button (Enter / click opens it); gets the card's on-screen box for the fly-in to the large view */
  onOpen?: (from?: DOMRect) => void;
  /** Large detail size: mouse / pen tilt, plus device tilt where allowed */
  large?: boolean;
  /** Keep shimmer/sparkle running (otherwise only on hover/focus, so a full binder stays idle) */
  live?: boolean;
  /** Pack reveal stamp ("New", "Upgrade", "Dupe +5") */
  badge?: string;
  /** Provenance badges (e.g. a Perfect Season pack) */
  marks?: string[];
  /** The owner picked this variant × finish as the player's display card (a small pin on the tile) */
  pinned?: boolean;
  /** Custom player art (art lab); replaces the photo / jersey inside .fut__art when given */
  art?: ReactNode;
  className?: string;
  style?: CSSProperties;
}

/**
 * FUT-style collectible: a shield-shaped card with the OVR, position, team logo and jersey number top left,
 * player art (a real legend's photo, or a team-coloured silhouette), the surname on a name bar and six 0–99
 * face stats in two columns. Three layers, each in its own place:
 *   FACE    the club's colours (cardFace.ts: home jersey gradient, trim accent; white text, contrast-checked)
 *   TIER    the frame: an inner band, name-bar rules, the tier gem and label (copper Common, steel blue Rare,
 *           amethyst Epic, black-ember Legendary with a darker vignette, ember sparkles and a LEGEND ribbon)
 *   FINISH  the outer rim: Base a plain rim in the tier colour, brushed Silver, polished Gold, rainbow Holo (with a
 *           prismatic overlay that follows the pointer / device tilt), named by the finish chip
 * Locked cards are dark silhouettes.
 */
const CollectibleCard = ({
  player,
  tier,
  finish,
  variant,
  autograph,
  kit,
  prizm,
  owned,
  ovr,
  number,
  stats,
  setNo,
  setTotal,
  hint,
  onOpen,
  large = false,
  live = false,
  badge,
  marks,
  pinned = false,
  art,
  className,
  style,
}: CollectibleCardProps) => {
  const ref = useRef<HTMLDivElement>(null);
  // One rAF-throttled pointer handler per hovered card: the box is measured once on enter, the pointer position is
  // stored on every move, and the CSS variables are written at most once a frame (no layout reads in between)
  const frame = useRef(0);
  const box = useRef<DOMRect | null>(null);
  const point = useRef<[number, number] | null>(null);
  const pressTimer = useRef(0);
  const realLegend = !!player.isRealLegend;
  const team = findNFLTeam(player.team);
  const photo = owned && realLegend && player.photo?.url ? player.photo : null;
  const jerseyId = `j${useId().replace(/:/g, '')}`;
  const posName = POSITION_NAMES[player.position] ?? player.position;
  const mark = owned && marks?.length ? marks[marks.length - 1] : null;
  const FinishIcon = FINISH_ICON[finish];
  const TierIcon = TIER_ICON[tier];
  const surname = surnameOf(player.name);
  // A Prizm colour parallel only shows on the Prizm number art
  const par = owned && variant === 'number' && prizm ? prizm : undefined;
  // Idle animation (owner: subtle, super rare cards only): Holo finish or Legendary tier
  const idle = owned && (finish === 'holo' || tier === 'legendary');
  useEffect(() => {
    const el = ref.current;
    if (!idle || !el) return;
    return observeIdle(el);
  }, [idle]);
  // Every owned card tilts toward the pointer: mouse only in grids, mouse or pen at detail size. Never a finger: a
  // touch drag there is a scroll or a swipe-to-close, and phones tilt the large card with the device instead.
  const tilts = owned;

  const setVars = (x: number, y: number) => {
    const el = ref.current;
    if (!el) return;
    x = Math.min(1, Math.max(0, x));
    y = Math.min(1, Math.max(0, y));
    el.style.setProperty('--fut-rx', `${((0.5 - y) * (large ? 18 : 16)).toFixed(2)}deg`);
    el.style.setProperty('--fut-ry', `${((x - 0.5) * (large ? 22 : 18)).toFixed(2)}deg`);
    el.style.setProperty('--fut-mx', `${(x * 100).toFixed(1)}%`);
    el.style.setProperty('--fut-my', `${(y * 100).toFixed(1)}%`);
    // Centred pointer (-0.5…0.5): drives the transform-only light, glare and shadow layers
    el.style.setProperty('--fut-px', (x - 0.5).toFixed(3));
    el.style.setProperty('--fut-py', (y - 0.5).toFixed(3));
    el.dataset.tilt = 'on';
  };
  const apply = () => {
    frame.current = 0;
    const r = box.current;
    const p = point.current;
    if (r && p && r.width) setVars((p[0] - r.left) / r.width, (p[1] - r.top) / r.height);
  };
  const onMove = (e: PointerEvent<HTMLDivElement>) => {
    const el = ref.current;
    if (!tilts || !el || e.pointerType === 'touch' || (!large && e.pointerType !== 'mouse') || !motionOk()) return;
    if (!box.current) box.current = el.getBoundingClientRect();
    point.current = [e.clientX, e.clientY];
    if (!frame.current) frame.current = requestAnimationFrame(apply);
  };
  const onLeave = () => {
    const el = ref.current;
    if (frame.current) cancelAnimationFrame(frame.current);
    frame.current = 0;
    box.current = null;
    point.current = null;
    if (!el) return;
    ['--fut-rx', '--fut-ry', '--fut-mx', '--fut-my', '--fut-px', '--fut-py'].forEach((k) => el.style.removeProperty(k));
    delete el.dataset.tilt;
  };
  // Touch: no tilt on drag; a tap shows a brief press (the springy return comes from the card's transition)
  const release = () => {
    window.clearTimeout(pressTimer.current);
    pressTimer.current = window.setTimeout(() => {
      if (ref.current) delete ref.current.dataset.press;
    }, 120);
  };
  const onDown = (e: PointerEvent<HTMLDivElement>) => {
    // Intent prefetch: the card detail's market panel needs market.json (usually in already; then a no-op)
    if (onOpen) void loadMarket();
    if (e.pointerType !== 'touch' || !onOpen || !ref.current) return;
    window.clearTimeout(pressTimer.current);
    ref.current.dataset.press = 'on';
  };
  useEffect(
    () => () => {
      if (frame.current) cancelAnimationFrame(frame.current);
      window.clearTimeout(pressTimer.current);
    },
    [],
  );

  // Large view: device tilt drives the same variables (iOS asks permission on the first tap)
  useEffect(() => {
    if (!large || !owned || typeof window === 'undefined' || !('DeviceOrientationEvent' in window) || !motionOk()) return;
    const onTilt = (e: DeviceOrientationEvent) => {
      if (e.beta == null || e.gamma == null) return;
      const x = Math.min(1, Math.max(0, 0.5 + e.gamma / 50));
      const y = Math.min(1, Math.max(0, 0.5 + (e.beta - 45) / 60));
      setVars(x, y);
    };
    const DOE = window.DeviceOrientationEvent as unknown as { requestPermission?: () => Promise<string> };
    let asked = false;
    const ask = () => {
      if (asked || typeof DOE.requestPermission !== 'function') return;
      asked = true;
      DOE.requestPermission()
        .then((r) => r === 'granted' && window.addEventListener('deviceorientation', onTilt))
        .catch(() => undefined);
    };
    const el = ref.current;
    if (typeof DOE.requestPermission === 'function') el?.addEventListener('pointerdown', ask);
    else window.addEventListener('deviceorientation', onTilt);
    return () => {
      el?.removeEventListener('pointerdown', ask);
      window.removeEventListener('deviceorientation', onTilt);
    };
    // setVars only touches the ref
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [large, owned]);

  const vars = {
    ...style,
    ...(team ? { '--fut-a': `hsl(${team.primaryColor})`, '--fut-b': `hsl(${team.secondaryColor})` } : {}),
    // Team-colour face (owned cards only; locked cards stay dark silhouettes)
    ...(owned ? cardFaceVars(player.team) : {}),
    // Idle cards start their loops at different points, so a binder never pulses in sync
    ...(idle ? { '--fut-idle-delay': `-${idleOffset(player.name)}ms` } : {}),
  } as CSSProperties;

  const setLabel = setNo != null && setTotal ? `card ${setNo} of ${setTotal}` : null;
  const label = owned
    ? `${displayName(player.name)}, ${pinned ? 'your display card, ' : ''}${variant ? `${variantLabel(variant)} variant, ` : ''}${par ? `${prizmInfo(par.c).label} parallel ${prizmSerial(par)}, ` : ''}${tierLabel(tier)} tier, ${finishLabel(finish)} finish, ${ovr != null ? `${CAREER_LABEL} ${ovr}, ` : ''}${posName}${team ? `, ${team.name}` : ''}${number != null ? `, number ${number}` : ''}${setLabel ? `, ${setLabel}` : ''}${mark ? `, ${mark}` : ''}${onOpen ? '. Open card' : ''}`
    : `Locked ${tierLabel(tier)} card, ${posName}${hint ? `. ${hint}` : ''}`;

  // The Autograph variant is the whole card (owner: "i want that art to be the card … it deserves to be the full
  // card"): the signed autograph fills the face edge to edge; no OVR, number, name bar, stats or tier pip on top.
  // Only the rim, foil, holo, light and glare (and Legendary sparks) stay, so its finish and tier still read.
  const fullAuto = owned && variant === 'auto' && art == null && !photo;

  const face = (
    <>
      {owned && !large && (
        <span className="fut__aura" aria-hidden="true">
          <i />
        </span>
      )}
      <span className="fut__shape" aria-hidden="true">
      <span className="fut__face">
        {fullAuto ? (
          <span className="fut__art fut__art--auto">
            <VariantArt variant="auto" player={player} number={number} finish={finish} autograph={autograph} />
          </span>
        ) : (
        <>
        <span className="fut__pattern" />
        {/* Prizm colour parallel: a refractor wash and shimmer stripes in its colour across the face, under the art */}
        {par && <span className="fut__par" />}
        <span className={cn('fut__art', art == null && photo && 'fut__art--photo')}>
          {art != null ? (
            art
          ) : photo ? (
            <img src={photo.url} alt="" loading="lazy" decoding="async" referrerPolicy="no-referrer" draggable={false} />
          ) : owned && variant ? (
            <VariantArt variant={variant} player={player} number={number} finish={finish} kit={kit} autograph={autograph} prizm={par} />
          ) : (
            <PlayerJersey number={owned ? number : null} id={jerseyId} />
          )}
        </span>
        <span className="fut__meta">
          <span className="fut__ovr">{owned ? (ovr ?? '–') : '?'}</span>
          <span className="fut__pos">{player.position}</span>
          {owned && (
            <span className="fut__logo">
              {realLegend && !team ? <span className="fut__star">★</span> : <TeamLogo team={player.team} size={48} decorative />}
            </span>
          )}
          {owned && number != null && <span className="fut__num">#{number}</span>}
          {owned && (
            <span className={cn('fut__fchip', `fut__fchip--${finish}`)}>
              <FinishIcon />
              {finishLabel(finish)}
            </span>
          )}
        </span>
        <span className={cn('fut__name', surname.length > 9 && 'fut__name--long', surname.length > 12 && 'fut__name--xl')}>
          {owned ? surname : '? ? ?'}
        </span>
        <span className="fut__stats">
          {(stats ?? []).slice(0, 6).map((s) => (
            <span key={s.code} className="fut__stat">
              <b>{owned ? (s.value ?? '–') : '··'}</b>
              <span>{s.code}</span>
            </span>
          ))}
        </span>
        {owned && (
          <span className="fut__pip">
            <TierIcon />
            {tierLabel(tier)}
            {variant && <span className="fut__vtag">· {par ? `${variantShort(variant)} ${prizmInfo(par.c).label}` : variantShort(variant)}</span>}
          </span>
        )}
        </>
        )}
        {owned && finish !== 'base' && <span className="fut__foil" />}
        {owned && finish === 'holo' && <span className="fut__holo" />}
        {owned && <span className="fut__light" />}
        {owned && <span className="fut__glare" />}
        {owned && tier === 'legendary' && (
          <span className="fut__sparks">
            {SPARKS.map(([x, y], i) => (
              <i key={i} style={{ left: `${x}%`, top: `${y}%`, animationDelay: `${(i * 0.37).toFixed(2)}s` }} />
            ))}
          </span>
        )}
      </span>
      {/* Idle light, Holo and Legendary only (very slow, staggered per card, paused off screen): a faint rainbow sheen
          across rim and face, a few rising embers. The art never moves. */}
      {idle && finish === 'holo' && <span className="fut__idle" />}
      {idle && tier === 'legendary' && (
        <span className="fut__embers">
          <i />
          <i />
          <i />
        </span>
      )}
      </span>
    </>
  );

  const extras = (
    <>
      {owned && tier === 'legendary' && !fullAuto && (
        <span className="fut__ribbon" aria-hidden="true">
          {realLegend ? 'NFL Legend' : 'Legend'}
        </span>
      )}
      {badge && (
        <span className={cn('fut__badge', badge.startsWith('Dupe') && 'fut__badge--muted')} aria-hidden="true">
          {badge}
        </span>
      )}
      {mark && (
        <span className="fut__mark" aria-hidden="true" title={mark}>
          18–0
        </span>
      )}
      {owned && pinned && (
        <span className="fut__pin" aria-hidden="true" title="Your display card">
          <Pin />
        </span>
      )}
    </>
  );

  return (
    <div
      ref={ref}
      className={cn(
        'fut',
        owned ? [`fut--${tier}`, `fut--f-${finish}`, variant && `fut--v-${variant}`, par && `fut--p-${par.c}`] : 'fut--locked',
        realLegend && owned && 'fut--nfl',
        large && 'fut--lg',
        live && 'fut--live',
        className,
      )}
      style={vars}
      data-key={`${player.position}:${displayName(player.name)}`}
      data-idle={idle ? '' : undefined}
      onPointerMove={tilts ? onMove : undefined}
      onPointerLeave={tilts ? onLeave : undefined}
      onPointerDown={onOpen ? onDown : undefined}
      onPointerUp={onOpen ? release : undefined}
      onPointerCancel={onOpen ? release : undefined}
    >
      {owned && !large && (
        <span className="fut__shadow" aria-hidden="true">
          <i />
        </span>
      )}
      {onOpen ? (
        <button type="button" className="fut__card" onClick={() => onOpen(ref.current?.getBoundingClientRect())} aria-label={label}>
          {face}
          {extras}
        </button>
      ) : (
        <div className="fut__card" role="img" aria-label={label}>
          {face}
          {extras}
        </div>
      )}
    </div>
  );
};

export default CollectibleCard;
